package br.com.onda;
import android.content.*;import android.graphics.*;import android.media.*;import android.net.Uri;import java.io.*;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class PhotoVideoTest {
 final Context c=getInstrumentation().getTargetContext();
 File file(String suffix)throws Exception{return File.createTempFile("photo-video-test-",suffix,c.getCacheDir());}
 File picture()throws Exception{File photo=file(".png");Bitmap b=Bitmap.createBitmap(64,96,Bitmap.Config.ARGB_8888);try(OutputStream out=new FileOutputStream(photo)){b.eraseColor(Color.CYAN);assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));}finally{b.recycle();}return photo;}
 File fixture(String name)throws Exception{File out=file(".input");try(InputStream in=getInstrumentation().getContext().getAssets().open(name);OutputStream stream=new FileOutputStream(out)){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)stream.write(bytes,0,n);}return out;}
 JSONObject verify(File video)throws Exception{MediaExtractor ex=new MediaExtractor();boolean sound=false,picture=false;long audioDuration=0,videoDuration=0;int width=0,height=0;try{ex.setDataSource(video.getPath());assertEquals(2,ex.getTrackCount());for(int i=0;i<ex.getTrackCount();i++){MediaFormat f=ex.getTrackFormat(i);String mime=f.getString(MediaFormat.KEY_MIME);if("audio/mp4a-latm".equals(mime)){sound=true;audioDuration=f.getLong(MediaFormat.KEY_DURATION);}if("video/avc".equals(mime)){picture=true;videoDuration=f.getLong(MediaFormat.KEY_DURATION);width=f.getInteger(MediaFormat.KEY_WIDTH);height=f.getInteger(MediaFormat.KEY_HEIGHT);}}assertTrue(sound&&picture);assertTrue(audioDuration>1000000);assertTrue(Math.abs(audioDuration-videoDuration)<1200000);assertTrue(width>0&&width<=1280&&height>0&&height<=1280);}finally{ex.release();}MediaMetadataRetriever retriever=new MediaMetadataRetriever();try{retriever.setDataSource(video.getPath());Bitmap frame=retriever.getFrameAtTime(0,MediaMetadataRetriever.OPTION_CLOSEST_SYNC);assertNotNull(frame);frame.recycle();}finally{retriever.release();}return new JSONObject().put("bytes",video.length()).put("h264",picture).put("aac",sound).put("width",width).put("height",height).put("audioUs",audioDuration).put("videoUs",videoDuration).put("decodedFrame",true);}
 void report(String key,JSONObject value)throws Exception{File f=new File(c.getFilesDir(),"photo-video-tests.json");JSONObject all=f.exists()?new JSONObject(new String(java.nio.file.Files.readAllBytes(f.toPath()),java.nio.charset.StandardCharsets.UTF_8)):new JSONObject();all.put(key,value);java.nio.file.Files.write(f.toPath(),all.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 @Test public void stillPhotoAndAacBecomePlayableMp4WithoutChangingOriginals()throws Exception{File photo=picture(),audio=fixture("audio.m4a"),out=file(".mp4");byte[] original=java.nio.file.Files.readAllBytes(photo.toPath());try{PhotoVideo.create(photo,audio,out,()->{});JSONObject proof=verify(out);assertEquals(64,proof.getInt("width"));assertEquals(96,proof.getInt("height"));assertArrayEquals(original,java.nio.file.Files.readAllBytes(photo.toPath()));MediaMetadataRetriever retriever=new MediaMetadataRetriever();try{retriever.setDataSource(out.getPath());Bitmap frame=retriever.getFrameAtTime(0);assertNotNull(frame);int color=frame.getPixel(frame.getWidth()/2,frame.getHeight()/2);assertTrue(Color.green(color)>150&&Color.blue(color)>150&&Color.red(color)<130);frame.recycle();}finally{retriever.release();}report("aacCopy",proof.put("originalPhotoPreserved",true));}finally{photo.delete();audio.delete();out.delete();}}
 @Test public void mp3SoundtrackIsConvertedToAacAndCancellationCleansTemps()throws Exception{File photo=picture(),audio=fixture("audio.m4a"),mp3=file(".mp3"),out=file(".mp4");try{Mp3Converter.convert(audio,mp3,192,()->{});PhotoVideo.create(photo,mp3,out,()->{});JSONObject proof=verify(out);int[] calls={0};try{PhotoVideo.create(photo,mp3,out,()->{if(++calls[0]>4)throw new InterruptedIOException("Cancelado");});fail();}catch(InterruptedIOException expected){}File[] leftovers=c.getCacheDir().listFiles((d,name)->name.startsWith("onda-download-photo-"));assertNotNull(leftovers);assertEquals(0,leftovers.length);report("mp3ToAac",proof.put("cancelledAndCleaned",true));}finally{photo.delete();audio.delete();mp3.delete();out.delete();}}
 @Test public void userPhotoLinkCreatesCompleteSharedVideoWhenPubliclyAvailable()throws Exception{JSONObject proof=new JSONObject();try{YoutubeDownloads.Result result;try{result=MediaDownloads.inspect("https://vt.tiktok.com/ZSphEcQP7/");}catch(Exception error){proof.put("analysis","provider-unavailable").put("reason",DownloadFailure.describe("Consulta",error));return;}YoutubeDownloads.Option option=null;for(YoutubeDownloads.Option candidate:result.options)if(candidate.photoVideo){option=candidate;break;}if(option==null){proof.put("analysis","no-photo-audio-combination");return;}File out=file(".mp4");Intent job=new Intent(c,MediaDownloadService.class).putExtra("photo_video",true).putExtra("request_cookies",option.requestCookies).putExtra("first",option.first).putExtra("second",option.second).putExtra("original",false).putExtra("referer",option.referer).putExtra("format","mp4").putExtra("destination",Uri.fromFile(out).toString()).putExtra("title","Foto com música");try{c.getSharedPreferences("downloads",0).edit().putString("status","").commit();getInstrumentation().runOnMainSync(()->c.startForegroundService(job));long end=System.currentTimeMillis()+180000;String status="";while(System.currentTimeMillis()<end){status=c.getSharedPreferences("downloads",0).getString("status","");if(!MediaDownloadService.activeDownload&&(status.startsWith("Download concluído")||status.startsWith("Operação interrompida")))break;Thread.sleep(200);}assertTrue(status,status.startsWith("Download concluído"));proof=verify(out).put("analysis","downloaded-complete-mp4");}finally{c.stopService(job);out.delete();}}finally{report("userLink",proof);}}
}
